198	        }
199	        record("PERSON_EDITED", sheetId, user, person, today,
200	                (termsChanged ? termsField(terms) : "") + (contactChanged ? contactField(contact) : ""));
201	        rollup.recordChanges(sheetId, user, before);
202	        return person;
203	    }
204	
205	    /** Give each of the people of {@code ids}, in list order, {@code grade} from {@code gradeFrom}
206	     *  (null: the sheet's today) as saving them in the person form would, each written with its
207	     *  PERSON_EDITED and rollup lines; all or none. Refused (404) when any is not on the sheet. */
208	    @Transactional
209	    public int grade(String sheetId, String user, List<Long> ids, String grade, LocalDate gradeFrom) {
210	        Set<Long> wanted = Set.copyOf(ids);
211	        List<Person> chosen = people.findBySheetIdOrderByIdAsc(sheetId).stream()
212	                .filter(p -> wanted.contains(p.getId())).toList();
213	        if (chosen.size() != wanted.size()) {
214	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person");
215	        }
