220	                person.recordGrade(grade, gradeFrom != null ? gradeFrom : today);
221	            }
222	            try {
223	                people.flush();
224	            } catch (ObjectOptimisticLockingFailureException e) {
225	                throw savedByAnother(); // saved by another user at the same moment
226	            }
227	            record("PERSON_EDITED", sheetId, user, person, today, "");
228	            rollup.recordChanges(sheetId, user, before);
229	        }
230	        return chosen.size();
231	    }
232	
233	    /** Retire a person from a date (a missing one takes the sheet's today); they count as retired
234	     *  at once. Retiring them again moves the date. From the day the date is reached their open
235	     *  claims, unless bound by a statement, leave the live totals. */
236	    @Transactional
237	    public Person retire(String sheetId, String user, long id, LocalDate from) {
238	        Person person = people.findForUpdate(id, sheetId)
239	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
240	        LocalDate on = from != null ? from : sheets.today(sheetId);
241	        RollupService.Snapshot before = rollup.snapshot(sheetId);
242	        person.setRetiredFrom(on);
243	        people.flush();
244	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
245	                + " name=" + person.getName() + " from=" + on);
246	        rollup.recordChanges(sheetId, user, before);
247	        return person;
248	    }
249	
250	    /** Add a hold to a person from a date (a missing one takes the sheet's today) to an optional
251	     *  one; their OPEN claims dated within it then count in no live total, unless bound by a
252	     *  statement. A to-date before the from-date is refused (422). */
253	    @Transactional
254	    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
255	        Person person = people.findForUpdate(id, sheetId)
256	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
257	        LocalDate on = from != null ? from : sheets.today(sheetId);
258	        if (to != null && to.isBefore(on)) {
259	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "The to-date is before the from-date");
260	        }
261	        RollupService.Snapshot before = rollup.snapshot(sheetId);
262	        person.addHold(on, to);
263	        people.flush();
264	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user
265	                + " name=" + person.getName() + " from=" + on);
266	        rollup.recordChanges(sheetId, user, before);
267	        return person;
268	    }
269	
270	    /** Written with the grade in force on {@code today}, the sheet's today, then {@code extra}. */
271	    private void record(String event, String sheetId, String user, Person person, LocalDate today, String extra) {
272	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
273	                + " name=" + person.getName() + " grade=" + person.gradeOn(today) + extra);
274	    }
275	
276	    /** The terms field of a person's record: the days, empty when none. */
277	    private static String termsField(Integer terms) {
278	        return " terms=" + (terms == null ? "" : terms);
279	    }
