305	    private void requireUnusedName(String sheetId, Long exceptId, String name) {
306	        boolean taken = people.findBySheetIdAndNameIgnoreCase(sheetId, name).stream()
307	                .anyMatch(p -> !p.getId().equals(exceptId));
