26	/** A person on a sheet, with a name and a dated grade (A, B or C). */
27	@Entity
28	@EntityListeners(HistoryListener.class)
29	@Table(name = "person")
30	public class Person {
31	
32	    @Id
33	    @GeneratedValue(strategy = GenerationType.IDENTITY)
34	    private Long id;
35	
36	    @Column(name = "sheet_id", nullable = false)
37	    private String sheetId;
38	
39	    @Column(name = "name", nullable = false)
40	    private String name;
41	
42	    /** The first grade the person was given: in force from the beginning of time until a later one. */
43	    @Column(name = "grade", nullable = false)
44	    private String grade;
45	
46	    /** The grades recorded since, by the date each is in force from. */
47	    @ElementCollection(fetch = FetchType.EAGER)
48	    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
49	    @MapKeyColumn(name = "from_date")
50	    @Column(name = "grade", nullable = false)
51	    private Map<LocalDate, String> datedGrades = new HashMap<>();
52	
53	    /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
54	    @Column(name = "terms")
55	    private Integer terms;
56	
57	    /** The person's contact, trimmed and lower-cased; null when they have none. */
58	    @Column(name = "contact")
59	    private String contact;
60	
61	    /** The date the person is retired from; null while not retired. Set, they count as retired
62	     *  at once, whatever the date. */
63	    @Column(name = "retired_from")
64	    private LocalDate retiredFrom;
65	
66	    /** The person's holds, in the order they were added: their OPEN claims dated within one count
67	     *  in no live total (unless bound by a statement). */
68	    @ElementCollection(fetch = FetchType.EAGER)
69	    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
70	    @OrderColumn(name = "position")
71	    private List<Hold> holds = new ArrayList<>();
72	
73	    /** Raised on every save, so an edit of a version someone else has since saved is refused. */
74	    @Version
75	    @Column(name = "version", nullable = false)
76	    private long version;
77	
78	    protected Person() {
79	    }
80	
81	    public Person(String sheetId, String name, String grade) {
82	        this.sheetId = sheetId;
83	        this.name = name;
84	        this.grade = grade;
85	    }
86	
87	    public Long getId() {
88	        return id;
89	    }
90	
91	    public String getSheetId() {
92	        return sheetId;
93	    }
94	
95	    public String getName() {
96	        return name;
97	    }
98	
99	    public void setName(String name) {
100	        this.name = name;
101	    }
102	
103	    /** A grade and the date it is in force from (null: from the beginning of time). */
104	    public record DatedGrade(String grade, LocalDate from) {
105	    }
106	
107	    /** The grade in force on a date: the one with the latest from-date on or before it, else the first. */
108	    public String gradeOn(LocalDate on) {
109	        Map.Entry<LocalDate, String> latest = new TreeMap<>(datedGrades).floorEntry(on);
110	        return latest == null ? grade : latest.getValue();
111	    }
112	
113	    /** Record a grade from a date, in place of any recorded from the same date. */
114	    public void recordGrade(String grade, LocalDate from) {
115	        datedGrades.put(from, grade);
