    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const claim = await this.api.remind(sheetId, c.id);
      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: remindError(e) }));
